'use strict';
let accountFilter='all',methodFilter='all',sortBy='date-desc',page=1,rangeKey='month',customStart='',customEnd='',budgetCategory='all',refreshing=false;
const typeLabels={income:'Income',expense:'Expense',transfer:'Transfer',repayment:'Card repayment',buy:'Investment purchase',sell:'Investment sale',contribution:'Goal contribution',withdrawal:'Goal withdrawal'};
const typeName=t=>typeLabels[t]||t;
const today=()=>F.dateString(new Date(),state.settings.timezone);
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'Missing account';
const current=()=>F.calculate(state);
function formatDate(d){if(!F.validDate(d))return '';if(state.settings.dateFormat==='YYYY-MM-DD')return d;if(state.settings.dateFormat==='DD/MM/YYYY')return d.slice(8)+'/'+d.slice(5,7)+'/'+d.slice(0,4);return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
function setStatus(message){$('#save-status').textContent=message;}
function setBusy(value){document.querySelectorAll('button[type=submit],#confirm-go').forEach(b=>b.disabled=value);}
function showError(message){$('#app-error').hidden=false;$('#app-error').innerHTML=esc(message)+' <button class="text-button" data-action="reload">Reload saved data</button>';setStatus('Not saved');toast(message);const local=$('#form-error');if(local)local.textContent=message;}
const options=(values,selected)=>values.map(v=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('');
const selectOptions=(pairs,selected)=>pairs.map(([v,l])=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(l)+'</option>').join('');
const field=(name,label,value='',type='text',extra='')=>'<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
const select=(name,label,pairs,value,extra='')=>'<label>'+label+'<select name="'+name+'" '+extra+'>'+selectOptions(pairs,value)+'</select></label>';
const pairs=values=>values.map(v=>[v,v]);
const amountField=(name,label,value='')=>field(name,label,value,'number','min="0.01" max="10000000000" step=".01" required');
const notesField=value=>'<label>Notes<textarea name="notes" maxlength="2000" rows="3">'+esc(value||'')+'</textarea></label>';
const dateField=(value=today(),name='date',label='Date')=>field(name,label,value,'date','max="'+today()+'" required');
const activeAccounts=(nonCredit=false)=>state.accounts.filter(a=>!a.archived&&(!nonCredit||a.type!=='Credit Card')).map(a=>[a.id,a.name+(a.type==='Credit Card'?' (credit card)':'')]);
function form(title,kind,id,body){openModal(title,'<form id="'+kind+'-form" data-kind="'+kind+'" data-id="'+esc(id||'')+'">'+body+'<p id="form-error" class="coral" role="alert"></p><button class="button primary" type="submit">Save '+(kind==='entry'?'transaction':kind)+'</button></form>');}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function closeModal(){if(!busy)$('#modal').close();}
function confirmAction(title,description,label,fn){openModal(title,'<p class="confirm-text">'+esc(description)+'</p><p id="form-error" class="coral" role="alert"></p><div class="confirm-actions"><button class="button ghost" id="confirm-cancel">Cancel</button><button class="button danger" id="confirm-go">'+esc(label)+'</button></div>');$('#confirm-cancel').onclick=closeModal;$('#confirm-go').onclick=async()=>{if(await fn())closeModal();};}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function transactionRows(rows,editable=true){return rows.length?'<div class="table-wrap" tabindex="0"><table><thead><tr><th>Transaction</th><th>Date</th><th>Type / account</th><th class="right">Amount</th><th>Actions</th></tr></thead><tbody>'+rows.map(t=>'<tr><td><button class="text-button" data-detail="'+esc(t.id)+'">'+esc(t.name)+'</button><small>'+esc(t.category||'')+'</small></td><td>'+shortDate(t.date)+'</td><td>'+typeName(t.type)+'<small>'+esc(accountName(t.accountId))+(t.toAccountId?' → '+esc(accountName(t.toAccountId)):'')+'</small></td><td class="right financial">'+money(t.amount,2)+'</td><td class="table-actions">'+(editable?'<button class="icon-button" data-edit-entry="'+esc(t.id)+'" aria-label="Edit '+esc(t.name)+'">'+icon('edit')+'</button><button class="icon-button" data-delete-entry="'+esc(t.id)+'" aria-label="Delete '+esc(t.name)+'">'+icon('trash')+'</button>':'')+'</td></tr>').join('')+'</tbody></table></div>':empty('No transactions','There are no matching records for this selection.');}
function overviewExtra(){const n=current(),s=F.summary(state,month);return '<div class="functional-section stat-strip">'+stat('Total cash',n.cash,'Across active non-credit accounts')+stat('Goal allocations',n.allocated,'Already included in cash')+stat('Net worth',n.netWorth,'All accounts + holdings; goals counted once')+'</div><div class="settings-grid"><article class="panel"><h3>Monthly financial summary</h3><div class="allocation-row"><span>Net cash flow</span><strong class="financial">'+money(s.net)+'</strong></div><div class="allocation-row"><span>Savings rate</span><strong>'+s.savingsRate.toFixed(1)+'%</strong></div><div class="allocation-row"><span>Credit-card debt</span><strong class="financial">'+money(n.liabilities)+'</strong></div><div class="allocation-row"><span>Savings goal allocations</span><strong class="financial">'+money(n.savings)+'</strong></div><button class="button portfolio-link" data-view="reports">View reports '+icon('arrow')+'</button></article><article class="panel"><div class="panel-header"><h3>Financial goals</h3><button class="text-button" data-view="goals">See all</button></div>'+state.goals.filter(g=>!g.archived).slice(0,3).map(g=>{const x=F.goal(state,g);return '<div class="budget-item"><div class="budget-row"><span>'+esc(g.name)+'</span><small class="financial">'+money(x.amount)+' / '+money(g.target)+'</small></div><div class="progress"><div style="width:'+Math.min(100,x.pct)+'%;background:var(--chart-teal)"></div></div></div>';}).join('')+(!state.goals.some(g=>!g.archived)?empty('Your next milestone','Create a savings or investment goal.','add-goal','Create goal'):'')+'</article></div>';}
function rangeControls(){return '<div class="toolbar"><select id="range-filter" aria-label="Date range">'+selectOptions([['month','This Month'],['week','This Week'],['last-month','Last Month'],['3-months','Last 3 Months'],['6-months','Last 6 Months'],['year','This Year'],['custom','Custom Date Range'],['selected','Selected reporting month']],rangeKey)+'</select>'+(rangeKey==='custom'?'<label>From <input type="date" id="range-start" value="'+esc(customStart)+'" aria-label="Start date"></label><label>To <input type="date" id="range-end" value="'+esc(customEnd)+'" aria-label="End date"></label>':'')+'</div>';}
function selectedRange(){return rangeKey==='selected'?F.period(month):F.range(rangeKey,today(),{start:customStart||today().slice(0,7)+'-01',end:customEnd||today()});}
function filteredTransactions(){const r=selectedRange();return state.transactions.filter(t=>t.date>=r.start&&t.date<=r.end&&(typeFilter==='all'||t.type===typeFilter)&&(categoryFilter==='all'||t.category===categoryFilter)&&(accountFilter==='all'||t.accountId===accountFilter||t.toAccountId===accountFilter)&&(methodFilter==='all'||t.paymentMethod===methodFilter)&&[t.name,t.category,t.notes,t.paymentMethod,accountName(t.accountId),accountName(t.toAccountId)].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sortBy==='amount-desc'?b.amount-a.amount:sortBy==='amount-asc'?a.amount-b.amount:sortBy==='date-asc'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));}
function transactionTable(){const rows=filteredTransactions(),pages=Math.max(1,Math.ceil(rows.length/25));page=Math.min(page,pages);return transactionRows(rows.slice((page-1)*25,page*25))+'<div class="pagination"><span>'+rows.length+' records · Page '+page+' of '+pages+'</span><button class="button ghost" data-page="-1" '+(page<=1?'disabled':'')+'>Previous</button><button class="button ghost" data-page="1" '+(page>=pages?'disabled':'')+'>Next</button></div>';}
function transactions(){const s=F.summary(state,selectedRange());return '<div class="stat-strip">'+stat('Income',s.income,'Selected range','green')+stat('Expenses',s.expense,'Selected range')+stat('Net cash flow',s.net,'Income minus expenses')+'</div><article class="panel panel-pad">'+rangeControls()+'<div class="toolbar"><input class="search-field" id="search" placeholder="Search title, source or notes" aria-label="Search transactions" value="'+esc(search)+'"><select id="type-filter" aria-label="Transaction type">'+selectOptions([['all','All types'],...F.types.map(t=>[t,typeName(t)])],typeFilter)+'</select><select id="category-filter" aria-label="Category">'+selectOptions([['all','All categories'],...pairs([...new Set([...state.categories.expense,...state.categories.income])])],categoryFilter)+'</select><select id="account-filter" aria-label="Account">'+selectOptions([['all','All accounts'],...state.accounts.map(a=>[a.id,a.name])],accountFilter)+'</select><select id="method-filter" aria-label="Payment method">'+selectOptions([['all','All payment methods'],...pairs([...new Set(state.transactions.map(t=>t.paymentMethod))])],methodFilter)+'</select><select id="sort-filter" aria-label="Sort transactions">'+selectOptions([['date-desc','Newest first'],['date-asc','Oldest first'],['amount-desc','Highest amount'],['amount-asc','Lowest amount']],sortBy)+'</select><button class="button ghost" data-action="export-csv">'+icon('download')+' Export CSV</button></div><div id="transaction-results">'+transactionTable()+'</div></article>';}
function accounts(){return '<div class="settings-actions"><button class="button" data-action="transfer">Transfer money</button><button class="button" data-action="repayment">Repay credit card</button></div><div class="budget-grid functional-section">'+current().accounts.map(a=>'<article class="panel budget-large"><div class="panel-header"><h3>'+esc(a.name)+'</h3><span class="help-tag">'+esc(a.type)+'</span></div><div class="money">'+amountHtml(a.type==='Credit Card'?Math.max(0,-a.balance):a.balance)+'</div><p class="notice">'+(a.type==='Credit Card'?'Outstanding debt'+(a.balance>0?' · Credit balance '+money(a.balance):''):'Unallocated '+money(a.balance-a.allocated))+(a.archived?' · Archived':'')+'</p><div class="settings-actions"><button class="text-button" data-edit-account="'+esc(a.id)+'">Edit</button><button class="text-button" data-account-history="'+esc(a.id)+'">History</button><button class="text-button" data-archive-account="'+esc(a.id)+'">'+(a.archived?'Unarchive':'Archive')+'</button><button class="text-button" data-delete-account="'+esc(a.id)+'">Delete</button></div></article>').join('')+'</div><p class="notice">Credit-card purchases count as expenses. Repayments reduce cash and debt without creating a second expense. Archive only zero-balance accounts.</p>';}
function investments(){const n=current();return '<div class="stat-strip">'+stat('Remaining cost basis',n.cost,'Weighted average cost after sales')+stat('Current value',n.value,'Manual valuations')+stat('Unrealized return',n.gain,n.returnPct.toFixed(2)+'% · Realized '+money(n.realized),n.gain<0?'coral':'green')+'</div><div class="holdings-grid"><article class="panel panel-pad"><div class="panel-header"><h3>Your holdings</h3><span class="help-tag">MANUALLY UPDATED</span></div>'+(n.holdings.length?'<div class="table-wrap" tabindex="0"><table><thead><tr><th>Investment</th><th>Units / remaining cost</th><th>Value / gain</th><th>Actions</th></tr></thead><tbody>'+n.holdings.map(h=>'<tr><td>'+esc(h.name)+'<small>'+esc(h.asset)+' · Valued '+shortDate(h.date)+'</small></td><td class="financial">'+h.units+'<small>'+money(h.costBasis)+' · Total purchased '+money(h.totalInvested)+'</small></td><td class="financial">'+money(h.value)+'<small class="'+(h.gain<0?'coral':'green')+'">'+money(h.gain)+' ('+h.returnPct.toFixed(2)+'%)</small></td><td><div class="settings-actions"><button class="text-button" data-trade="buy" data-holding="'+esc(h.id)+'">Buy</button><button class="text-button" data-trade="sell" data-holding="'+esc(h.id)+'">Sell</button><button class="text-button" data-edit-holding="'+esc(h.id)+'">Edit / value</button><button class="text-button" data-holding-history="'+esc(h.id)+'">History</button><button class="text-button" data-delete-holding="'+esc(h.id)+'">Delete</button></div></td></tr>').join('')+'</tbody></table></div>':empty('Build your portfolio','Record your first purchase or an existing opening holding.','add-holding','Add investment'))+'<p class="notice">Purchases debit the selected account. Sales credit it and reduce cost basis using weighted average cost. Opening positions are already owned and do not move cash.</p></article>'+portfolioCard()+'</div>';}
function goals(){return '<div class="stat-strip">'+stat('Savings allocations',current().savings,'Existing cash assigned to savings goals')+stat('All goal allocations',current().allocated,'Savings and investment goals')+stat('Unallocated cash',current().available,'Total cash minus all goal allocations')+'</div><div class="budget-grid">'+state.goals.map(g=>{const x=F.goal(state,g),net=state.transactions.filter(t=>t.goalId===g.id&&t.date.startsWith(month)).reduce((n,t)=>n+(t.type==='contribution'?t.amount:-t.amount),0);return '<article class="panel budget-large"><div class="panel-header"><h3>'+esc(g.name)+'</h3><span class="help-tag">'+g.type+(g.archived?' · Archived':'')+'</span></div><div class="money">'+amountHtml(x.amount)+'</div><p class="notice">'+money(x.remaining)+' remaining · '+x.pct.toFixed(1)+'%</p><div class="progress"><div style="width:'+Math.min(100,x.pct)+'%;background:var(--chart-teal)"></div></div><p class="notice">Target '+shortDate(g.targetDate)+'<br>'+monthName()+': '+money(net)+' / '+money(g.monthlyTarget)+' monthly target</p><div class="settings-actions">'+(!g.archived?'<button class="text-button" data-goal-entry="contribution" data-goal="'+esc(g.id)+'">Contribute</button><button class="text-button" data-goal-entry="withdrawal" data-goal="'+esc(g.id)+'">Withdraw</button>':'')+'<button class="text-button" data-edit-goal="'+esc(g.id)+'">Edit</button><button class="text-button" data-goal-history="'+esc(g.id)+'">History</button><button class="text-button" data-archive-goal="'+esc(g.id)+'">'+(g.archived?'Unarchive':'Archive')+'</button><button class="text-button" data-delete-goal="'+esc(g.id)+'">Delete</button></div></article>';}).join('')+'</div>'+(!state.goals.length?empty('Give your money a purpose','Goals allocate money you already have.','add-goal','Create a goal'):'')+'<p class="notice">Investment goals earmark cash for a future purchase; withdraw the allocation before buying. Allocations never increase cash or net worth. To reallocate, withdraw from one goal and contribute to another.</p>';}
function budgetMini(b){const x=F.budget(state,b,month);return '<div class="budget-item"><div class="budget-row"><span>'+esc(b.category)+'</span><small class="financial">'+money(x.spent)+' / '+money(b.limit)+'</small></div><div class="progress"><div style="width:'+Math.min(100,x.pct)+'%;background:'+(x.pct>100?'var(--negative)':x.pct>=75?'var(--warning)':'var(--chart-teal)')+'"></div></div><small class="subtle">'+x.status+'</small></div>';}
function budgets(){const all=F.monthlyBudgets(state,month),rows=all.filter(b=>budgetCategory==='all'||b.category===budgetCategory),overall=all.find(b=>b.category==='All expenses'),limit=overall?.limit||all.reduce((n,b)=>n+b.limit,0),spent=overall?F.summary(state,month).expense:all.reduce((n,b)=>n+F.spending(state,month,b.category),0);return '<div class="stat-strip">'+stat('Monthly plan',limit,monthName())+stat('Spent',spent,overall?'All expenses':'Budgeted categories')+stat('Remaining',limit-spent,'Transfers and purchases excluded')+'</div><div class="toolbar"><select id="budget-category" aria-label="Budget category">'+selectOptions([['all','All budgets'],...pairs(['All expenses',...state.categories.expense])],budgetCategory)+'</select></div><div class="budget-grid">'+rows.map(b=>{const x=F.budget(state,b,month);return '<article class="panel budget-large"><div class="panel-header"><h3>'+esc(b.category)+'</h3><div><button class="icon-button" data-edit-budget="'+esc(b.id)+'" aria-label="Edit budget">'+icon('edit')+'</button><button class="icon-button" data-delete-budget="'+esc(b.id)+'" aria-label="Delete budget">'+icon('trash')+'</button></div></div><div class="money">'+amountHtml(x.spent)+'</div>'+budgetMini(b)+'<p class="notice financial">'+x.pct.toFixed(1)+'% used · '+money(x.remaining)+' remaining'+(b.month==='*'?'<br>Imported repeating limit':'')+'</p></article>';}).join('')+'</div>'+(!rows.length?empty('Plan this month','Set an overall or category limit.','add-budget','Create budget'):'');}
function breakdown(rows,by,type){const sums=Object.create(null);for(const t of rows.filter(t=>t.type===type))sums[t[by]||'Other']=(sums[t[by]||'Other']||0)+F.cents(t.amount);return Object.entries(sums).map(([name,n])=>({name,value:n/100})).sort((a,b)=>b.value-a.value);}
function reportBars(items){const max=Math.max(1,...items.map(x=>x.value));return items.length?items.map(x=>'<div class="budget-item"><div class="budget-row"><span>'+esc(x.name)+'</span><strong class="financial">'+money(x.value)+'</strong></div><div class="progress" role="img" aria-label="'+esc(x.name+': '+money(x.value))+'"><div style="width:'+x.value/max*100+'%;background:var(--chart-teal)"></div></div></div>').join(''):'<p class="notice">No records in this range.</p>';}
function reports(){const r=selectedRange(),s=F.summary(state,r),n=current(),months=[];let d=r.start.slice(0,7);while(d<=r.end.slice(0,7)&&months.length<120){const p=F.period(d),x=F.summary(state,{start:p.start<r.start?r.start:p.start,end:p.end>r.end?r.end:p.end});months.push({month:d,...x});const [y,m]=d.split('-').map(Number);d=new Date(Date.UTC(y,m,1)).toISOString().slice(0,7);}const max=Math.max(1,...months.flatMap(x=>[x.income,x.expense]));return rangeControls()+'<div class="stat-strip">'+stat('Income',s.income,'Selected dates')+stat('Expenses',s.expense,'Selected dates')+stat('Net cash flow',s.net,'Savings rate '+s.savingsRate.toFixed(1)+'%')+'</div><article class="panel panel-pad"><div class="panel-header"><h3>Income vs expense · Monthly comparison</h3><button class="button ghost" data-action="report-csv">Export CSV</button></div><div class="report-chart">'+months.map(x=>'<div class="report-month"><span>'+x.month+'</span><div class="comparison-bars"><div class="income-bar" style="width:'+x.income/max*100+'%" title="Income '+money(x.income)+'"></div><div class="expense-bar" style="width:'+x.expense/max*100+'%" title="Expenses '+money(x.expense)+'"></div></div><small class="financial">'+money(x.income)+' / '+money(x.expense)+'</small></div>').join('')+'</div><p class="notice">Green: income · Coral: expenses. Transfers, trades and goal allocations are excluded. '+(months.length===120?'Chart limited to 120 months; export includes the full range.':'')+'</p></article><div class="settings-grid functional-section"><article class="panel"><h3>Spending by category · Highest first</h3>'+reportBars(breakdown(s.rows,'category','expense'))+'</article><article class="panel"><h3>Income by source</h3>'+reportBars(breakdown(s.rows,'name','income'))+'</article><article class="panel"><h3>Current account balances</h3>'+n.accounts.map(a=>'<div class="allocation-row"><span>'+esc(a.name)+'</span><strong class="financial">'+money(a.balance)+'</strong></div>').join('')+'</article><article class="panel"><h3>Current investment performance</h3>'+n.holdings.map(h=>'<div class="allocation-row"><span>'+esc(h.name)+'</span><strong class="financial">'+money(h.gain)+' ('+h.returnPct.toFixed(1)+'%)</strong></div>').join('')+'<p class="notice">Latest manual valuations; account balances and investment values are current, not filtered historical snapshots. Realized gains: '+money(n.realized)+'.</p></article></div>';}
function recurring(){const due=F.due(state);return '<article class="panel panel-pad"><div class="panel-header"><h3>'+due.length+' entries due</h3><button class="button primary" data-action="post-due" '+(!due.length?'disabled':'')+'>Post due entries</button></div><p class="notice">Up to 1,000 due entries are shown per batch. Scheduled entries are posted only after you review them here. Open the app to catch up; it does not run while closed. Each occurrence has a unique ID. Deleting a posted occurrence will not recreate it.</p>'+transactionRows(due,false)+'</article><div class="budget-grid functional-section">'+state.recurring.map(r=>'<article class="panel budget-large"><h3>'+esc(r.name)+'</h3><p class="notice financial">'+money(r.template.amount)+' · '+r.frequency+'<br>'+typeName(r.template.type)+' · '+esc(accountName(r.template.accountId))+'<br>Next: '+shortDate(F.nextOccurrence(r.startDate,r.nextIndex,r.frequency))+' · '+(r.active?'Active':'Paused')+'</p><div class="settings-actions"><button class="text-button" data-edit-recurring="'+esc(r.id)+'">Edit</button><button class="text-button" data-toggle-recurring="'+esc(r.id)+'">'+(r.active?'Pause':'Resume')+'</button><button class="text-button" data-delete-recurring="'+esc(r.id)+'">Delete schedule</button></div></article>').join('')+'</div>';}
function settings(){return '<div class="settings-grid"><article class="panel"><h3>Profile & preferences</h3><form id="settings-form" data-kind="settings">'+field('name','Your name',state.settings.name,'text','required maxlength="60"')+select('currency','Display currency',pairs(['INR','USD','EUR','GBP']),state.settings.currency)+field('timezone','Timezone',state.settings.timezone,'text','required placeholder="Asia/Kolkata"')+select('dateFormat','Date format',pairs(['DD MMM YYYY','DD/MM/YYYY','YYYY-MM-DD']),state.settings.dateFormat)+select('defaultAccount','Default account',activeAccounts(),state.settings.defaultAccount)+'<p class="form-note">Currency changes labels only; amounts are not converted. Entries are date-only in your selected timezone. The current dark theme is retained.</p><button class="button primary" type="submit">Save preferences</button></form></article><article class="panel"><h3>Data & backups</h3><p>'+esc(store.mode)+'. One owner workspace. Hosted records are shared across your signed-in devices; browser-only exports stay on that device. Prices are manual. Keep secure backups.</p><div class="settings-actions"><button class="button" data-action="backup">Download JSON backup</button><button class="button ghost" data-action="restore">Restore backup</button><input type="file" id="import-file" accept=".json,application/json" hidden><button class="button ghost" data-action="reload">Reload saved data</button><button class="button ghost" data-action="load-demo">Explore separate demo</button>'+(state.demo?'<button class="button" data-action="leave-demo">Return to real data</button>':'')+'</div><p class="notice">Demo changes never replace your real records. Restore replaces the current workspace only. Older v1 backups are migrated automatically.</p>'+state.migrationNotes.map(n=>'<p class="notice">'+esc(n)+'</p>').join('')+'</article><article class="panel full"><div class="panel-header"><h3>Transaction categories</h3><button class="button" data-action="add-category">Add category</button></div><div class="category-grid">'+['income','expense'].map(type=>'<div><h3>'+typeName(type)+'</h3>'+state.categories[type].map(c=>'<div class="allocation-row"><span>'+icon(catIcons[c]||'other')+esc(c)+'</span><div><button class="text-button" data-edit-category="'+esc(c)+'" data-category-type="'+type+'">Edit</button><button class="text-button" data-delete-category="'+esc(c)+'" data-category-type="'+type+'">Delete</button></div></div>').join('')+'</div>').join('')+'</div></article><article class="panel full danger-zone"><h3>Reset workspace</h3><p>Download a backup first. This clears financial records in the current workspace.</p><button class="button danger" data-action="start-fresh">Clear data & start fresh</button></article></div>';}

function entryForm(id,type='expense',linked={}){
  const existing=state.transactions.find(t=>t.id===id),t=existing||{type,name:'',amount:'',date:today(),accountId:state.settings.defaultAccount,paymentMethod:'UPI',notes:'',...linked};type=t.type;
  let body=field('name',type==='income'?'Income title / source':'Transaction title',t.name,'text','required maxlength="100"')+'<input type="hidden" name="type" value="'+type+'"><div class="form-row">'+amountField('amount','Amount ('+state.settings.currency+')',t.amount)+dateField(t.date)+'</div>';
  const accounts=existing?state.accounts.map(a=>[a.id,a.name]):activeAccounts(!['income','expense'].includes(type));
  body+=select('accountId',['contribution','withdrawal'].includes(type)?'Allocation account':'Account',accounts,t.accountId);
  if(['income','expense'].includes(type))body+=select('category','Category',pairs(state.categories[type]),t.category||state.categories[type][0]);
  if(['transfer','repayment'].includes(type))body+=select('toAccountId','Destination account',state.accounts.filter(a=>!a.archived&&(type==='repayment'?a.type==='Credit Card':a.type!=='Credit Card')).map(a=>[a.id,a.name]),t.toAccountId)+'<p class="form-note">Moves money between accounts. Does not count as income or expense.</p>';
  if(['buy','sell'].includes(type))body+=select('holdingId','Investment',state.holdings.map(h=>[h.id,h.name]),t.holdingId)+field('units','Units',t.units||'','number','min="0.00000001" max="10000000000" step="any" required')+'<p class="form-note">Enter total '+(type==='buy'?'purchase cost including fees':'sale proceeds after fees')+'. Cost basis uses weighted average cost.</p>';
  if(['contribution','withdrawal'].includes(type))body+=select('goalId','Goal',state.goals.filter(g=>!g.archived||g.id===t.goalId).map(g=>[g.id,g.name]),t.goalId)+'<p class="form-note">This changes the allocation of existing cash. It does not move money or count as income/expense.</p>';
  body+=field('paymentMethod','Payment method',t.paymentMethod,'text','required maxlength="60" list="payment-methods"')+'<datalist id="payment-methods"><option>UPI</option><option>Cash</option><option>Card</option><option>Bank transfer</option></datalist>'+notesField(t.notes);
  if(!existing&&['income','expense'].includes(type))body+=select('repeat','Repeat',pairs(['One time','weekly','monthly','yearly']),'One time');
  form((id?'Edit ':'Add ')+typeName(type),'entry',id,body);
}
const transactionForm=(id,type='expense')=>entryForm(id,type);
function accountForm(id){const a=state.accounts.find(a=>a.id===id)||{name:'',type:'Bank Account',openingBalance:0};form(id?'Edit account':'New account','account',id,field('name','Account name',a.name,'text','required maxlength="60"')+select('type','Account type',pairs(F.accountTypes),a.type)+field('openingBalance','Opening balance ('+state.settings.currency+')',a.openingBalance,'number','step=".01" min="-10000000000" max="10000000000" required')+'<p class="form-note">For credit cards, enter debt as a negative balance (for example -2000). An opening balance is prior money or debt, not new income.</p>');}
function holdingForm(id){const h=state.holdings.find(h=>h.id===id)||{name:'',symbol:'',asset:'Mutual funds',price:'',date:today(),openingDate:today(),openingUnits:0,openingCost:0,notes:''};let body=field('name','Investment name',h.name,'text','required maxlength="100"')+select('asset','Asset type',pairs(F.assets),h.asset)+field('symbol','Symbol (optional)',h.symbol||'','text','maxlength="12"');
  if(!id)body+=select('mode','How are you adding this?', [['purchase','New purchase — deduct cash'],['opening','Already owned — opening position']], 'purchase')+'<div class="form-row">'+field('units','Units','','number','min="0.00000001" max="10000000000" step="any" required')+field('cost','Purchase price per unit','','number','min="0" max="10000000000" step="any" required')+'</div>'+select('accountId','Funding account (new purchase)',activeAccounts(true),state.settings.defaultAccount)+dateField(today(),'openingDate','Purchase / opening date');
  else body+='<div class="form-row">'+field('openingUnits','Opening units',h.openingUnits,'number','min="0" max="10000000000" step="any" required')+field('openingCost','Opening total cost',h.openingCost,'number','min="0" max="10000000000" step=".01" required')+'</div>'+dateField(h.openingDate,'openingDate','Opening date')+'<p class="form-note">Opening positions do not move cash. To correct a purchase or sale, edit it in History. Changing opening units may invalidate later sales.</p>';
  body+='<div class="form-row">'+field('price','Current value per unit',h.price,'number','min="0" max="10000000000" step="any" required')+dateField(h.date,'date','Valuation date')+'</div>'+notesField(h.notes)+'<p class="form-note">Manual valuation only. For a deposit or property, use 1 unit and its total value.</p>';form(id?'Edit investment / valuation':'Add investment','holding',id,body);
}
function goalForm(id){const g=state.goals.find(g=>g.id===id)||{name:'',type:'savings',target:'',monthlyTarget:0,startDate:today(),targetDate:today(),notes:''};form(id?'Edit goal':'Create goal','goal',id,field('name','Goal name',g.name,'text','required maxlength="100"')+select('type','Goal type',pairs(['savings','investment']),g.type)+amountField('target','Target amount',g.target)+field('monthlyTarget','Monthly contribution target',g.monthlyTarget,'number','min="0" max="10000000000" step=".01" required')+'<div class="form-row">'+dateField(g.startDate,'startDate','Start date')+field('targetDate','Target date',g.targetDate,'date','required')+'</div>'+notesField(g.notes));}
function budgetForm(id){const b=state.budgets.find(b=>b.id===id)||{category:'All expenses',month,limit:''};form(id?'Edit budget':'Create monthly budget','budget',id,field('month','Budget month',b.month==='*'?month:b.month,'month','required')+select('category','Category',pairs(['All expenses',...state.categories.expense]),b.category)+amountField('limit','Monthly limit',b.limit)+(b.month==='*'?'<p class="form-note">Saving converts this imported repeating limit to the selected month. Other monthly budgets stay unchanged.</p>':''));}
function recurringForm(id){const r=state.recurring.find(r=>r.id===id),t=r?.template||{type:'expense',name:'',amount:'',category:state.categories.expense[0],accountId:state.settings.defaultAccount,paymentMethod:'UPI',notes:''};form(id?'Edit recurring schedule':'Create recurring schedule','recurring',id,field('name','Schedule / transaction title',r?.name||t.name,'text','required maxlength="100"')+select('type','Type',pairs(['income','expense']),t.type,'id="recurring-type"')+amountField('amount','Amount',t.amount)+select('category','Category',pairs(state.categories[t.type]),t.category,'id="recurring-category"')+select('accountId','Account',activeAccounts(),t.accountId)+field('paymentMethod','Payment method',t.paymentMethod,'text','required maxlength="60"')+select('frequency','Frequency',pairs(['weekly','monthly','yearly']),r?.frequency||'monthly',r&&r.nextIndex?'disabled':'')+field('startDate','Schedule start date',r?.startDate||today(),'date','required '+(r&&r.nextIndex?'readonly':''))+field('endDate','End date (optional)',r?.endDate||'','date')+notesField(t.notes)+'<p class="form-note">Month-end schedules clamp to the final day of short months. Changes apply to future unposted entries. To change timing after posting, pause this schedule and create another.</p>');}
function categoryForm(name,type='expense'){form(name?'Edit category':'Add category','category','',select('type','Type',pairs(['income','expense']),type,name?'disabled':'')+field('original','',name||'','hidden')+field('categoryType','',type,'hidden')+field('name','Category name',name||'','text','required maxlength="60"')+select('symbol','Icon',pairs(['other','food','shopping','transport','bills','entertainment','health','education','wallet']),catIcons[name]||'other')+'<p class="form-note">Renaming updates existing transactions, budgets and schedules.</p>');}
function details(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;openModal(t.name,'<dl class="detail-list">'+Object.entries({Type:typeName(t.type),Date:shortDate(t.date),Amount:money(t.amount,2),Account:accountName(t.accountId),...(t.toAccountId?{Destination:accountName(t.toAccountId)}:{}),Category:t.category||'—','Payment method':t.paymentMethod,Notes:t.notes||'—',...(t.holdingId?{Investment:state.holdings.find(h=>h.id===t.holdingId)?.name,Units:t.units}:{}),...(t.goalId?{Goal:state.goals.find(g=>g.id===t.goalId)?.name}:{}),'Record ID':t.id}).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl><button class="button" data-edit-entry="'+esc(id)+'">Edit transaction</button>');}
function history(title,rows){openModal(title,transactionRows([...rows].sort((a,b)=>b.date.localeCompare(a.date))));}
function upsert(s,key,record){const i=s[key].findIndex(x=>x.id===record.id);if(i<0)s[key].push(record);else s[key][i]=record;}
function csv(rows){const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';return [['Date','Title','Type','Category','Account','Destination','Payment method','Amount','Currency','Units','Investment','Goal','Notes'],...rows.map(t=>[t.date,t.name,typeName(t.type),t.category,accountName(t.accountId),t.toAccountId?accountName(t.toAccountId):'',t.paymentMethod,t.amount,state.settings.currency,t.units,state.holdings.find(h=>h.id===t.holdingId)?.name,state.goals.find(g=>g.id===t.goalId)?.name,t.notes])].map(r=>r.map(cell).join(',')).join('\r\n');}
function exportCSV(report=false){const r=selectedRange(),rows=report?state.transactions.filter(t=>t.date>=r.start&&t.date<=r.end):filteredTransactions();download('daddyvault-transactions-'+today()+'.csv','\uFEFF'+csv(rows),'text/csv;charset=utf-8');toast('CSV exported');}

document.addEventListener('submit',async e=>{
  const formElement=e.target,kind=formElement.dataset.kind;if(!kind)return;e.preventDefault();if(busy||!ready)return;
  const data=Object.fromEntries(new FormData(formElement)),id=formElement.dataset.id||uid();
  const success=await change(s=>{
    if(kind==='entry'){
      const old=s.transactions.find(t=>t.id===id),t={...old,id,type:data.type,name:data.name.trim(),amount:Number(data.amount),date:data.date,accountId:data.accountId,paymentMethod:data.paymentMethod.trim(),notes:data.notes||''};
      if(data.category)t.category=data.category;if(data.toAccountId)t.toAccountId=data.toAccountId;if(data.holdingId){t.holdingId=data.holdingId;t.units=Number(data.units);}if(data.goalId)t.goalId=data.goalId;
      upsert(s,'transactions',t);
      if(!old&&data.repeat&&data.repeat!=='One time'){const scheduleId=uid();t.recurringId=scheduleId;upsert(s,'recurring',{id:scheduleId,name:t.name,startDate:t.date,endDate:'',frequency:data.repeat,nextIndex:1,active:true,template:{...t}});}
    }
    if(kind==='account'){const old=s.accounts.find(a=>a.id===id);upsert(s,'accounts',{id,name:data.name.trim(),type:data.type,openingBalance:Number(data.openingBalance),archived:old?.archived||false});}
    if(kind==='holding'){
      const old=s.holdings.find(h=>h.id===id),units=Number(data.units),cost=F.round(units*Number(data.cost)),opening=old||data.mode==='opening';
      const h={id,name:data.name.trim(),symbol:data.symbol.trim(),asset:data.asset,price:Number(data.price),date:data.date,openingDate:data.openingDate,openingUnits:old?Number(data.openingUnits):opening?units:0,openingCost:old?Number(data.openingCost):opening?cost:0,notes:data.notes};upsert(s,'holdings',h);
      if(!old&&!opening)s.transactions.push({id:uid(),name:'Purchase: '+h.name,type:'buy',holdingId:id,units,amount:cost,date:data.openingDate,accountId:data.accountId,paymentMethod:'Bank transfer',notes:data.notes});
    }
    if(kind==='goal'){const old=s.goals.find(g=>g.id===id);upsert(s,'goals',{id,name:data.name.trim(),type:data.type,target:Number(data.target),monthlyTarget:Number(data.monthlyTarget),startDate:data.startDate,targetDate:data.targetDate,notes:data.notes,archived:old?.archived||false});}
    if(kind==='budget')upsert(s,'budgets',{id,month:data.month,category:data.category,limit:Number(data.limit)});
    if(kind==='settings')s.settings={...s.settings,name:data.name.trim(),currency:data.currency,timezone:data.timezone.trim(),dateFormat:data.dateFormat,defaultAccount:data.defaultAccount};
    if(kind==='recurring'){
      const old=s.recurring.find(r=>r.id===id);upsert(s,'recurring',{id,name:data.name.trim(),startDate:old?.nextIndex?old.startDate:data.startDate,endDate:data.endDate,frequency:old?.nextIndex?old.frequency:data.frequency,nextIndex:old?.nextIndex||0,active:old?.active??true,template:{name:data.name.trim(),type:data.type,category:data.category,amount:Number(data.amount),accountId:data.accountId,paymentMethod:data.paymentMethod.trim(),notes:data.notes,date:data.startDate}});
    }
    if(kind==='category'){
      const type=data.original?data.categoryType:data.type,name=data.name.trim();if(s.categories[type].includes(name)&&name!==data.original)throw Error('That category already exists.');
      if(data.original){s.categories[type]=s.categories[type].map(c=>c===data.original?name:c);s.transactions.forEach(t=>{if(t.type===type&&t.category===data.original)t.category=name;});s.recurring.forEach(r=>{if(r.template.type===type&&r.template.category===data.original)r.template.category=name;});if(type==='expense')s.budgets.forEach(b=>{if(b.category===data.original)b.category=name;});}else s.categories[type].push(name);
      s.categoryIcons[name]=data.symbol;
    }
  },'Saved successfully');
  if(success){$('#app-error').hidden=true;if(kind!=='settings')closeModal();}
});

document.addEventListener('click',async e=>{
  const button=e.target.closest('button');if(!button)return;const d=button.dataset;if(busy)return;
  if(d.action==='reload'||d.action==='leave-demo'){if($('#modal').open)closeModal();await initialize();return;}
  if(!ready)return;
  if(d.view){go(d.view);return;}if(d.chart){chartMode=d.chart;render();return;}
  if(d.page){page+=Number(d.page);$('#transaction-results').innerHTML=transactionTable();return;}
  if(d.detail){details(d.detail);return;}
  if(d.editEntry){entryForm(d.editEntry);return;}
  if(d.editAccount){accountForm(d.editAccount);return;}
  if(d.editHolding){holdingForm(d.editHolding);return;}
  if(d.editGoal){goalForm(d.editGoal);return;}
  if(d.editBudget){budgetForm(d.editBudget);return;}
  if(d.editRecurring){recurringForm(d.editRecurring);return;}
  if(d.editCategory){categoryForm(d.editCategory,d.categoryType);return;}
  if(d.trade){entryForm(null,d.trade,{holdingId:d.holding,name:(d.trade==='buy'?'Buy: ':'Sell: ')+state.holdings.find(h=>h.id===d.holding).name,paymentMethod:'Bank transfer'});return;}
  if(d.goalEntry){entryForm(null,d.goalEntry,{goalId:d.goal,name:typeName(d.goalEntry)+': '+state.goals.find(g=>g.id===d.goal).name,paymentMethod:'Allocation'});return;}
  for(const [key,field,title] of [['accountHistory','accountId','Account history'],['holdingHistory','holdingId','Investment history'],['goalHistory','goalId','Contribution history']])if(d[key]){history(title,state.transactions.filter(t=>t[field]===d[key]||(field==='accountId'&&t.toAccountId===d[key])));return;}
  if(d.toggleRecurring){await change(s=>{const r=s.recurring.find(r=>r.id===d.toggleRecurring);r.active=!r.active;},'Schedule updated');return;}
  if(d.archiveAccount||d.archiveGoal){const key=d.archiveAccount?'accounts':'goals',id=d.archiveAccount||d.archiveGoal;confirmAction('Change archive status?','Archived records remain in history. Accounts must have zero balance and cannot be your default account. Goal allocations must be withdrawn before archiving.','Continue',()=>change(s=>{const item=s[key].find(x=>x.id===id);if(key==='goals'&&!item.archived&&F.goal(s,item).amount>0)throw Error('Withdraw this goal’s allocations before archiving.');item.archived=!item.archived;},'Archive status updated'));return;}
  for(const [key,collection,label] of [['deleteEntry','transactions','transaction'],['deleteAccount','accounts','account'],['deleteHolding','holdings','investment'],['deleteGoal','goals','goal'],['deleteBudget','budgets','budget'],['deleteRecurring','recurring','schedule']])if(d[key]){
    const id=d[key];confirmAction('Delete '+label+'?','This removes the '+label+'. Linked financial history is preserved: delete linked entries first if necessary. Historical edits that would invalidate a later sale or allocation are rejected.','Delete',()=>change(s=>{
      if(collection==='accounts'&&(s.transactions.some(t=>t.accountId===id||t.toAccountId===id)||s.recurring.some(r=>r.template.accountId===id)))throw Error('This account has history or schedules. Archive it instead.');
      if(collection==='holdings'&&s.transactions.some(t=>t.holdingId===id))throw Error('This investment has trades. Delete or correct its trades first; keep sold positions to retain history.');
      if(collection==='goals'&&s.transactions.some(t=>t.goalId===id))throw Error('This goal has allocation history. Withdraw its allocation and archive it instead.');
      s[collection]=s[collection].filter(x=>x.id!==id);
    },'Deleted'));return;
  }
  if(d.deleteCategory){confirmAction('Delete category?','Categories in use cannot be deleted. Rename them to update their linked records.','Delete',()=>change(s=>{const type=d.categoryType,name=d.deleteCategory;if(s.transactions.some(t=>t.type===type&&t.category===name)||s.recurring.some(r=>r.template.type===type&&r.template.category===name)||(type==='expense'&&s.budgets.some(b=>b.category===name)))throw Error('This category is in use. Rename it instead.');s.categories[type]=s.categories[type].filter(c=>c!==name);},'Category deleted'));return;}
  const action=d.action;
  if(action==='add-transaction')entryForm();if(action==='add-income')entryForm(null,'income');if(action==='add-holding')holdingForm();if(action==='add-account')accountForm();if(action==='add-goal')goalForm();if(action==='add-budget')budgetForm();if(action==='add-recurring')recurringForm();if(action==='add-category')categoryForm();
  if(action==='transfer'||action==='repayment')entryForm(null,action,{name:action==='transfer'?'Account transfer':'Credit-card repayment',paymentMethod:'Bank transfer'});
  if(action==='toggle-privacy')$('#privacy-toggle').onclick();
  if(action==='export-csv')exportCSV();if(action==='report-csv')exportCSV(true);
  if(action==='backup')download('daddyvault-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');
  if(action==='restore')$('#import-file').click();
  if(action==='load-demo'){try{state=store.enterDemo();render();toast('Separate demo workspace opened');}catch(e){showError(e.message);}}
  if(action==='post-due')confirmAction('Post due recurring entries?','Post '+F.due(state).length+' due entries. All entries will be validated and saved together.','Post entries',()=>change(s=>F.postDue(s,today()),'Recurring entries posted'));
  if(action==='start-fresh'){
    confirmAction('Clear all financial records?','This clears the current workspace. Download a backup first. This cannot be undone in the app.','Clear workspace',()=>change(s=>{const next=F.emptyState({...s.settings,openingBalance:0,defaultAccount:'cash'});next.demo=s.demo;Object.assign(s,next);},'Workspace cleared'));
  }
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;page=1;$('#transaction-results').innerHTML=transactionTable();}});
document.addEventListener('change',async e=>{
  const id=e.target.id,v=e.target.value;try{
    if(id==='month-filter'){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(v))return;month=v;if(view==='transactions')rangeKey='selected';render();}
    const filters={'type-filter':x=>typeFilter=x,'category-filter':x=>categoryFilter=x,'account-filter':x=>accountFilter=x,'method-filter':x=>methodFilter=x,'sort-filter':x=>sortBy=x};
    if(filters[id]){filters[id](v);page=1;$('#transaction-results').innerHTML=transactionTable();}
    if(id==='range-filter'){rangeKey=v;page=1;render();}
    if(id==='range-start'||id==='range-end'){const next={start:id==='range-start'?v:customStart||today().slice(0,7)+'-01',end:id==='range-end'?v:customEnd||today()};F.range('custom',today(),next);customStart=next.start;customEnd=next.end;page=1;render();}
    if(id==='budget-category'){budgetCategory=v;render();}
    if(id==='recurring-type')$('#recurring-category').innerHTML=options(state.categories[v]);
    if(id==='import-file'){
      const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Backup exceeds 10 MB.');const imported=F.migrate(JSON.parse(await file.text()));
      if(!state.demo&&imported.demo)throw Error('Sample backups cannot replace real data. Open the demo workspace first.');
      confirmAction('Restore backup?','Replace the current workspace with '+imported.transactions.length+' transactions and '+imported.accounts.length+' accounts. Export a backup first.','Restore',()=>change(s=>Object.assign(s,{...imported,demo:state.demo}),'Backup restored'));e.target.value='';
    }
  }catch(err){showError(err.message);}
});
$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#privacy-toggle').onclick=()=>{hidden=!hidden;document.body.classList.toggle('privacy-hidden',hidden);if(ready)render();};
window.addEventListener('hashchange',()=>{if(!ready)return;const hash=location.hash.slice(1);if(navs.some(n=>n[0]===hash)){view=hash;render();}});
async function refreshSaved(){if(!ready||busy||refreshing||$('#modal').open||store.mode==='Sample workspace')return;refreshing=true;try{const next=await store.refresh();if(next){state=next;render();toast('Loaded newer saved records');}}catch(e){showError(e.message);}finally{refreshing=false;}}
window.addEventListener('focus',refreshSaved);window.addEventListener('storage',refreshSaved);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshSaved();});
async function initialize(){if(busy||refreshing)return;ready=false;setStatus('Loading saved records…');$('#content').innerHTML='<div class="empty-state">Loading your financial records…</div>';$('#app-error').hidden=true;try{if(window.VaultAuth)await VaultAuth.ensure();state=await store.load();ready=true;month=F.dateString(new Date(),state.settings.timezone).slice(0,7);view=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();const count=F.due(state).length;if(count)toast(count+' recurring entries are due. Review them under Recurring.');}catch(e){$('#content').innerHTML='<div class="empty-state"><h3>Saved records could not be loaded</h3><p>Your existing data has not been replaced.</p><button class="button primary" data-action="reload">Retry loading</button></div>';showError(e.message);}}
initialize();
